<script setup lang="ts">
import { Head, Link, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import type { ProgressionSnapshot, RewardItem } from '@/types/progression';
import type { InventorySnapshot } from '@/types/inventory';
import InventoryPanel from '@/components/InventoryPanel.vue';
import type { CommerceSummary } from '@/types/commerce';
import type { AccountSummary } from '@/types/account';
import AccountBalances from '@/components/AccountBalances.vue';
import AccountOrders from '@/components/AccountOrders.vue';
const props = defineProps<{ progression: ProgressionSnapshot; inventory: InventorySnapshot; commerce: CommerceSummary; account: AccountSummary }>();
const page = usePage(), track = ref('account');
defineOptions({ name: 'DashboardPage' });
const names: Record<string, string> = { damage: 'Damage', maximum_health: 'Maximum HP', movement_speed: 'Movement speed', pickup_radius: 'Pickup radius', ability_area: 'Ability area', cooldown_reduction: 'Cooldown reduction', damage_reduction: 'Incoming damage reduction', experience_gain: 'In-run experience' };
const labels: Record<string, string> = { credits: 'Credits', healing_potion: 'Healing Potion', movement_boost: 'Movement boost', damage_boost: 'Damage boost', revive: 'Revive', xp_boost_24h: '24-hour XP Boost', cosmetic_reward: 'Cosmetic reward' };
const rows = computed(() => props.progression.catalog.filter(row => row.track === track.value));
function itemLabel(item: RewardItem) { return item.type === 'permanent_stat_modifier' ? `${names[item.stat ?? ''] ?? item.stat}: +${(item.basis_points ?? 0) / 100}%` : `${labels[item.type] ?? item.type}${item.quantity ? ` × ${item.quantity}` : ''}`; }
function reached(at: number) { return props.progression.grants.find(grant => grant.track === track.value && grant.level === at); }
function duration(seconds: number) { const total = Math.floor(seconds); return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`; }
</script>
<template>
    <Head title="Account" />
    <section class="site-section dashboard-page">
        <p class="overline">PERMANENT PROGRESSION</p>
        <div class="section-heading"><div><h1>Welcome back,<br />{{ page.props.auth.user.name }}.</h1><p>Levels are stored on the server. Character bonuses apply to new runs.</p></div><a href="/play" class="site-button">Keep playing ↗</a></div>
        <AccountBalances :balances="account.balances" />
        <section class="account-recent"><div class="section-heading"><h2>Recent orders</h2><Link href="/account/orders">All orders →</Link></div><AccountOrders :entries="account.orders" /></section>
        <div class="profile-panel"><div><small>PROFILE</small><p>{{ page.props.auth.user.email }}</p><span>Email verified</span></div><Link href="/settings/profile" class="quiet-link">Settings →</Link><form action="/logout" method="post"><input type="hidden" name="_token" :value="page.props.csrfToken" /><button type="submit" class="quiet-link">Log out</button></form></div>
        <section class="progress-account" aria-label="Account Progress"><div><small>ACCOUNT LEVEL</small><h2 data-testid="account-level">{{ progression.account.level }} <span>/ 10</span></h2></div><div><progress :value="progression.account.level === 10 ? 100 : progression.account.xp" max="100" aria-label="Account XP" /><p>{{ progression.account.level === 10 ? 'Maximum level' : `${progression.account.xp} / 100 XP · next level in ${progression.account.xp_to_next} XP` }}</p><small>Defeat the final Warden: +50 XP. Defeat and practice: 0 Account XP.</small></div></section>
        <h2>Characters</h2>
        <div class="character-progress-grid"><article v-for="(hero, id) in progression.characters" :key="id" :data-testid="`character-${id}`"><p class="overline">{{ id }}</p><h3>Level {{ hero.level }} / 10</h3><progress :value="hero.level === 10 ? 100 : hero.xp" max="100" :aria-label="`${id} XP`" /><p>{{ hero.level === 10 ? 'Maximum level' : `${hero.xp} / 100 XP · ${hero.xp_to_next} XP to go` }}</p><dl><template v-for="(amount, stat) in hero.bonuses" :key="stat"><dt>{{ names[stat] ?? stat }}</dt><dd>{{ amount / 100 }}%</dd></template></dl><small>Damage bonuses add up: +5% at level 10. Cooldown and damage reduction are shown as reductions.</small></article></div>
        <section class="run-summary" aria-label="Run summary"><div><b>{{ progression.stats.wins }}</b><span>Victories</span></div><div><b>{{ progression.stats.defeats }}</b><span>Defeats</span></div><div><b>{{ duration(progression.stats.seconds) }}</b><span>Time played</span></div><div><b>{{ progression.stats.best_score.toLocaleString('en-US') }}</b><span>Best score</span></div></section>
        <h2>Run History</h2><nav class="operations-nav"><Link href="/runs">Full history →</Link><Link href="/leaderboard">Global Leaderboard →</Link><Link href="/settings/public-profile">Public name →</Link></nav><p class="subtle">This summary includes accepted regular runs. Results are checked against client data; this does not prove combat integrity. Practice grants no permanent XP.</p>
        <p v-if="!progression.runs.length" class="notice">No server runs yet. Previous local records are not imported as XP.</p>
        <div v-else class="progress-table-wrap"><table class="progress-table"><thead><tr><th>Character / mode</th><th>Result</th><th>Time</th><th>Score</th><th>Date</th></tr></thead><tbody><tr v-for="run in progression.runs" :key="run.id"><td>{{ run.character_id }}<small>{{ run.mode === 'practice' ? 'Practice · 0 XP' : 'Regular run' }}</small><small>Consumables: {{run.item_sequence??0}} · Revive: {{run.revive_count??0}}</small></td><td>{{ run.status === 'accepted' ? (run.record?.outcome === 'victory' ? 'Victory' : 'Defeat') : run.status === 'pending_review' ? 'Awaiting review · 0 XP' : run.status === 'active' ? 'Registered · unfinished' : 'Rejected' }}</td><td>{{ run.record ? duration(run.record.elapsed) : '—' }}</td><td>{{ run.record?.score ?? '—' }}</td><td>{{ new Date(run.started_at).toLocaleString('en-US') }}</td></tr></tbody></table></div>
        <section class="reward-section"><h2>Rewards</h2><p>Each level reached is recorded once. Item rewards are delivered to Inventory. Confirmed credits are added to Wallet; cosmetics await fulfillment.</p><label for="reward-track">Levels 1–10</label><select id="reward-track" v-model="track"><option value="account">Account</option><option v-for="(_, id) in progression.characters" :key="id" :value="`character:${id}`">{{ id }}</option></select><div class="progress-table-wrap"><table class="progress-table"><thead><tr><th>Level</th><th>Rewards / bonuses</th><th>Status</th></tr></thead><tbody><tr v-for="row in rows" :key="row.level"><td>{{ row.level }}</td><td><ul v-if="row.rewards.length"><li v-for="(item, i) in row.rewards" :key="i">{{ itemLabel(item) }}</li></ul><span v-else>Base level · achievement event</span></td><td>{{ !reached(row.level) ? 'Locked' : reached(row.level)?.fulfillment.some(item => item.status === 'pending_fulfillment') ? 'Earned · awaiting fulfillment' : 'Earned · fulfilled' }}</td></tr></tbody></table></div></section>
        <h3>Earned rewards</h3><ul class="grants-list"><li v-for="grant in progression.grants" :key="`${grant.track}:${grant.level}`"><b>{{ grant.track }} · level {{ grant.level }}</b><span v-if="!grant.fulfillment.length">Base level</span><span v-for="(item, i) in grant.fulfillment" :key="i">{{ itemLabel(item) }} · {{ item.status === 'fulfilled' ? (item.type === 'credits' ? 'added to Wallet' : 'added to Inventory') : item.status === 'pending_fulfillment' ? 'awaiting future fulfillment' : 'applies to new runs' }}</span></li></ul>
        <section class="commerce-preview" aria-label="Wallet and purchases"><div class="section-heading"><h2>Wallet</h2><Link href="/shop" class="site-button">Open Shop →</Link></div><Link href="/wallet" class="wallet-card"><small>AVAILABLE CREDITS</small><strong data-testid="dashboard-balance">{{ commerce.balance }}</strong><span>Open Wallet →</span></Link><Link href="/inventory#service-purchases" class="quiet-link">Game service purchases →</Link></section><InventoryPanel :snapshot="inventory" compact />
    </section>
</template>
